-- Report ID : RPT_052
-- Report    : ReIM Unmatched Receipts
-- Module    : Finance
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     sh.SHIPMENT                                          AS receipt_no,     sh.RECEIVE_DATE                                      AS receipt_date,     sh.ASN                                                AS asn_number,      oh.ORDER_NO                                          AS po_number,     oh.STATUS                                            AS po_status,     oh.OTB_EOW_DATE                                      AS po_date,      oh.SUPPLIER                                          AS supplier_id,     sp.SUP_NAME                                          AS supplier_name,     sp.SUP_STATUS                                        AS supplier_status,      ol.LOCATION                                          AS location_id,     ol.LOC_TYPE                                          AS loc_type,     CASE ol.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                  AS location_name,      ss.ITEM                                              AS item_id,     im.ITEM_DESC                                         AS item_description,     im.DEPT                                              AS dept_no,     d.DEPT_NAME                                          AS dept_name,      ss.QTY_RECEIVED                                      AS qty_received,     ss.UNIT_COST                                         AS unit_cost,     ROUND(ss.QTY_RECEIVED * ss.UNIT_COST, 2)            AS receipt_cost_value,      TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE)             AS days_since_receipt,     CASE         WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 0  AND 7              THEN '0 - 7 Days'         WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 8  AND 15              THEN '8 - 15 Days'         WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) BETWEEN 16 AND 30              THEN '16 - 30 Days'         WHEN TRUNC(SYSDATE) - TRUNC(sh.RECEIVE_DATE) > 30              THEN '30+ Days'     END                                                  AS aging_bucket,      ss.INVC_MATCH_STATUS                                 AS shipsku_match_status,     sh.INVC_MATCH_STATUS                                 AS shipment_match_status,     sh.INVC_MATCH_DATE                                   AS invoice_match_date,      dh.DOC_ID                                            AS reim_invoice_doc_id,     dh.STATUS                                            AS reim_doc_status,     dh.HOLD_STATUS                                       AS reim_hold_status,      CASE         WHEN ss.INVC_MATCH_STATUS IS NULL              OR ss.INVC_MATCH_STATUS IN ('U', 'UNM', 'UNMATCHED')             THEN 'NO INVOICE MATCHED TO RECEIPT'         WHEN ss.INVC_MATCH_STATUS = 'P'             THEN 'PARTIALLY MATCHED'         ELSE ss.INVC_MATCH_STATUS     END                                                  AS unmatched_reason,      TRUNC(SYSDATE)                                       AS report_date  FROM     MFCS_RDS.RDS_WV_SHIPMENT             sh     JOIN  MFCS_RDS.RDS_WV_SHIPSKU         ss   ON  sh.SHIPMENT       = ss.SHIPMENT     JOIN  MFCS_RDS.RDS_WV_ORDHEAD         oh   ON  sh.ORDER_NO       = oh.ORDER_NO     JOIN  MFCS_RDS.RDS_WV_ORDLOC          ol   ON  oh.ORDER_NO       = ol.ORDER_NO                                               AND  ss.ITEM            = ol.ITEM                                               AND  sh.TO_LOC          = ol.LOCATION     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER     im   ON  ss.ITEM            = im.ITEM     JOIN  MFCS_RDS.RDS_WV_DEPS            d    ON  im.DEPT            = d.DEPT     LEFT JOIN MFCS_RDS.RDS_WV_SUPS         sp  ON  oh.SUPPLIER        = sp.SUPPLIER     LEFT JOIN MFCS_RDS.RDS_WV_STORE        st  ON  ol.LOCATION        = st.STORE                                               AND  ol.LOC_TYPE         = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH          wh   ON  ol.LOCATION        = wh.WH                                               AND  ol.LOC_TYPE         = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_IM_DOC_HEAD  dh  ON  oh.ORDER_NO        = dh.ORDER_NO                                               AND  oh.SUPPLIER         = TO_NUMBER(dh.VENDOR)                                               AND  dh.STATUS          != 'M'     WHERE     (ss.INVC_MATCH_STATUS IS NULL      OR ss.INVC_MATCH_STATUS IN ('U', 'UNM', 'UNMATCHED', 'P'))      AND sh.RECEIVE_DATE >= ADD_MONTHS(SYSDATE, -3)     ORDER BY     days_since_receipt  DESC,     sp.SUP_NAME,     sh.SHIPMENT,     ss.ITEM